#!/usr/bin/env bash

tmp=''
work=''
step=init
output=''
shadow=''

main() {
  set -Eeuo pipefail
  [[ "${THOIDAI_RBAC_DRYRUN_APPROVED:-0}" == 1 ]] || { echo 'RBAC_DRYRUN_ERROR=approval required' >&2; return 1; }
  : "${BUNDLE_DIR:?BUNDLE_DIR is required}"; : "${POSTGRES_IMAGE:?POSTGRES_IMAGE is required}"
  command -v docker >/dev/null; command -v node >/dev/null
  local evidence="/opt/ops/thoidai-work/rbac-approval-evidence/dryrun-$(date -u +%Y%m%dT%H%M%SZ)" daily=/opt/ops/thoidai-work/backups/managed/daily
  tmp="rbac-approval-dryrun-$$"
  work=''
  output=''
  shadow=''
  local backup='' dump='' manifest='' db_password='' port='' before_file
  local expected_pass=21
  output="$evidence/behaviour.txt"; shadow="$evidence/shadow.txt"; before_file="$evidence/before-md5.txt"; mkdir -p "$evidence"
  cleanup() { local rc=$?; set +u; set +e; if [[ $rc -ne 0 ]]; then echo "RBAC_DRYRUN_RESULT=FAIL step=$step" >&2; [[ -f "$output" ]] && tail -n 20 "$output" >&2; [[ -f "$shadow" ]] && tail -n 20 "$shadow" >&2; fi; [[ -n "$tmp" ]] && docker rm -f -v "$tmp" >/dev/null 2>&1; [[ -n "$work" ]] && rm -rf -- "$work"; return "$rc"; }; trap cleanup EXIT
  step=disk; "$BUNDLE_DIR/scripts/production/disk-guard.sh"; work=$(mktemp -d)
  step=backup; while IFS= read -r entry; do [[ -f "$daily/$entry/postgres.dump" && -f "$daily/$entry/manifest.txt" ]] && { backup="$daily/$entry"; break; }; done < <(find "$daily" -mindepth 1 -maxdepth 1 -type d -name '*-daily' -printf '%f\n' | sort -r)
  [[ -n "$backup" ]]; dump="$backup/postgres.dump"; manifest="$backup/manifest.txt"; [[ "$(awk '$2=="postgres.dump" || $2=="*postgres.dump" {print $1; exit}' "$manifest")" == "$(sha256sum "$dump" | awk '{print $1}')" ]]
  step=postgres; if docker ps -a --format '{{.Names}}' | grep -Eq '^rbac-approval-dryrun-[^[:space:]]+$'; then echo 'RBAC_DRYRUN_ERROR=leftover dry-run container exists' >&2; return 1; fi; db_password=$(od -An -N24 -tx1 /dev/urandom | tr -d ' \n'); docker run -d --name "$tmp" --memory 512m -p 127.0.0.1::5432 -e POSTGRES_PASSWORD="$db_password" "$POSTGRES_IMAGE" >/dev/null
  for _ in $(seq 1 90); do docker exec "$tmp" pg_isready -h 127.0.0.1 -U supabase_admin -d postgres >/dev/null 2>&1 && break; sleep 2; done
  docker exec -i "$tmp" psql -q -h 127.0.0.1 -U supabase_admin -d postgres -v ON_ERROR_STOP=1 -c 'create schema if not exists supabase_migrations;' </dev/null >/dev/null
  docker exec -i "$tmp" pg_restore --schema=public --schema=supabase_migrations -h 127.0.0.1 -U supabase_admin -d postgres < "$dump" >"$work/restore.log" 2>&1 || true
  port=$(docker port "$tmp" 5432/tcp | sed -n 's/.*127.0.0.1:\([0-9]*\).*/\1/p' | head -n1); [[ "$port" =~ ^[0-9]+$ ]]
  export RBAC_DB_URL="postgresql://supabase_admin:$db_password@127.0.0.1:$port/postgres" SAFE_MIGRATION_MIGRATIONS_DIR="$BUNDLE_DIR/supabase/migrations"
  psql -q "$RBAC_DB_URL" -v ON_ERROR_STOP=1 -At -F'|' -c "select p.proname,md5(pg_get_functiondef(p.oid)) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('api_review_leave_request','api_review_personal_work_schedule','rbac_v2_scope_supported') order by p.proname" > "$before_file"
  step=apply; local apply_out; apply_out=$(MIGRATION_EVIDENCE_DIR="$evidence" "$BUNDLE_DIR/scripts/production/safe-apply-migration.sh" --file "$BUNDLE_DIR/supabase/migrations/20261028100000_rbac_approval_permissions_v1.sql" --db-url-env RBAC_DB_URL --postcondition-sql "$BUNDLE_DIR/scripts/production/rbac-approval/post/20261028100000_rbac_approval_permissions_v1.sql" --evidence-dir "$evidence"); echo "$apply_out"; grep -q '^PASS' <<<"$apply_out"; echo APPLIED; [[ "$(psql -q "$RBAC_DB_URL" -At -c "select count(*) from supabase_migrations.schema_migrations where version='20261028100000'")" == 1 ]]
  step=behaviour; psql -q "$RBAC_DB_URL" -v ON_ERROR_STOP=1 -f "$BUNDLE_DIR/supabase/tests/rbac_approval_v1_behaviour.sql" >"$output" 2>&1; local pass_count fail_count; pass_count=$(grep -c 'NOTICE:  RBAC_TEST_PASS' "$output" || true); fail_count=$(grep -c 'RBAC_TEST_FAIL' "$output" || true); [[ "$pass_count" == "$expected_pass" && "$fail_count" == 0 ]]
  step=shadow; psql -q -At "$RBAC_DB_URL" -v ON_ERROR_STOP=1 -f "$BUNDLE_DIR/scripts/production/rbac-approval-shadow-diff.sql" >"$shadow" 2>&1; local shadow_total shadow_mismatch; shadow_total=$(sed -n 's/^SHADOW_TOTAL=//p' "$shadow"); shadow_mismatch=$(sed -n 's/^SHADOW_MISMATCH=//p' "$shadow"); [[ "$shadow_total" =~ ^[1-9][0-9]*$ && "$shadow_mismatch" == 0 ]]
  step=idempotency; local grants_before permission_before function_before grants_after permission_after function_after; grants_before=$(psql -q "$RBAC_DB_URL" -At -c "select count(*) from public.role_permission_grants g join public.permissions p on p.id=g.permission_id where p.code in ('leave.approve','schedule.business.approve','schedule.event.approve')"); permission_before=$(psql -q "$RBAC_DB_URL" -At -c "select count(*) from public.permissions where code in ('leave.approve','schedule.business.approve','schedule.event.approve')"); function_before=$(psql -q "$RBAC_DB_URL" -At -c "select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('approval_effective_scopes','approval_review_basis','approval_assert_can_review','api_review_leave_request','api_review_personal_work_schedule','api_list_reviewable_leave_requests','api_list_reviewable_personal_plans','api_get_approval_capabilities','api_list_user_approval_permissions','api_list_user_permission_history')"); psql -q -v ON_ERROR_STOP=1 -f "$BUNDLE_DIR/supabase/migrations/20261028100000_rbac_approval_permissions_v1.sql" "$RBAC_DB_URL"; grants_after=$(psql -q "$RBAC_DB_URL" -At -c "select count(*) from public.role_permission_grants g join public.permissions p on p.id=g.permission_id where p.code in ('leave.approve','schedule.business.approve','schedule.event.approve')"); permission_after=$(psql -q "$RBAC_DB_URL" -At -c "select count(*) from public.permissions where code in ('leave.approve','schedule.business.approve','schedule.event.approve')"); function_after=$(psql -q "$RBAC_DB_URL" -At -c "select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('approval_effective_scopes','approval_review_basis','approval_assert_can_review','api_review_leave_request','api_review_personal_work_schedule','api_list_reviewable_leave_requests','api_list_reviewable_personal_plans','api_get_approval_capabilities','api_list_user_approval_permissions','api_list_user_permission_history')"); [[ "$grants_before" == "$grants_after" && "$permission_before" == "$permission_after" && "$function_before" == "$function_after" ]]
  step=revert; psql -q "$RBAC_DB_URL" -v ON_ERROR_STOP=1 -f "$BUNDLE_DIR/scripts/production/rbac-approval-v1-revert.sql" >/dev/null; diff -u "$before_file" <(psql -q "$RBAC_DB_URL" -At -F'|' -c "select p.proname,md5(pg_get_functiondef(p.oid)) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('api_review_leave_request','api_review_personal_work_schedule','rbac_v2_scope_supported') order by p.proname") >/dev/null
  [[ "$(psql -q "$RBAC_DB_URL" -At -c "select count(*) from supabase_migrations.schema_migrations where version='20261028100000'")" == 0 ]]
  [[ "$(psql -q "$RBAC_DB_URL" -At -c "select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('approval_effective_scopes','approval_review_basis','approval_assert_can_review','api_list_reviewable_leave_requests','api_list_reviewable_personal_plans','api_get_approval_capabilities','api_list_user_approval_permissions','api_list_user_permission_history')")" == 0 ]]
  [[ "$(psql -q "$RBAC_DB_URL" -At -c "select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('api_review_leave_request','api_review_personal_work_schedule','rbac_v2_scope_supported')")" == 3 ]]
  [[ "$(psql -q "$RBAC_DB_URL" -At -c "select count(*) from public.role_permission_grants g join public.permissions p on p.id=g.permission_id where p.code in ('leave.approve','schedule.business.approve','schedule.event.approve')")" == 0 ]]
  step=reapply; apply_out=$(MIGRATION_EVIDENCE_DIR="$evidence" "$BUNDLE_DIR/scripts/production/safe-apply-migration.sh" --file "$BUNDLE_DIR/supabase/migrations/20261028100000_rbac_approval_permissions_v1.sql" --db-url-env RBAC_DB_URL --postcondition-sql "$BUNDLE_DIR/scripts/production/rbac-approval/post/20261028100000_rbac_approval_permissions_v1.sql" --evidence-dir "$evidence"); echo "$apply_out"; grep -q '^PASS' <<<"$apply_out"; echo APPLIED; [[ "$(psql -q "$RBAC_DB_URL" -At -v ON_ERROR_STOP=1 -f "$BUNDLE_DIR/scripts/production/rbac-approval/post/20261028100000_rbac_approval_permissions_v1.sql")" == pass ]]
  step=behaviour_reapply; psql -q "$RBAC_DB_URL" -v ON_ERROR_STOP=1 -f "$BUNDLE_DIR/supabase/tests/rbac_approval_v1_behaviour.sql" >"$output" 2>&1; pass_count=$(grep -c 'NOTICE:  RBAC_TEST_PASS' "$output" || true); fail_count=$(grep -c 'RBAC_TEST_FAIL' "$output" || true); [[ "$pass_count" == "$expected_pass" && "$fail_count" == 0 ]]
  echo "RBAC_DRYRUN_RESULT=PASS EXPECTED_RBAC_TEST_PASS=$expected_pass RBAC_TEST_PASS=$pass_count RBAC_TEST_FAIL=$fail_count SHADOW_TOTAL=$shadow_total SHADOW_MISMATCH=$shadow_mismatch"
}
main "$@" </dev/null
